mapper.select:
SELECT w.id AS id, w.word AS word, w.normalized_word AS normalizedWord, w.phonetic0 AS phonetic0, w.phonetic1 AS phonetic1, w.trans AS trans, w.sentences AS sentences, w.phrases AS phrases, w.synos AS synos, w.rel_words AS relWords, w.etymology AS etymology, w.primary_pos AS primaryPos, w.primary_definition AS primaryDefinition, w.tags AS tags, ww.sequence_no AS sequenceNo, ww.difficulty_level AS difficultyLevel, ww.exam_frequency AS examFrequency FROM wordbook_word ww INNER JOIN word w ON w.id = ww.word_id AND w.deleted = 0 WHERE ww.deleted = 0 AND ww.enabled = 1 AND ww.wordbook_id = #{wordbookId}
AND ( w.word LIKE CONCAT('%', #{keyword}, '%') OR w.normalized_word LIKE CONCAT('%', #{keyword}, '%') OR w.primary_definition LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY ww.sequence_no ASC, w.id ASC

SELECT w.id AS id, ww.id AS relationId, w.word AS word, w.normalized_word AS normalizedWord, w.phonetic0 AS phonetic0, w.phonetic1 AS phonetic1, w.trans AS trans, w.sentences AS sentences, w.phrases AS phrases, w.synos AS synos, w.rel_words AS relWords, w.etymology AS etymology, w.primary_pos AS primaryPos, w.primary_definition AS primaryDefinition, w.tags AS tags, ww.sequence_no AS sequenceNo, ww.difficulty_level AS difficultyLevel, ww.exam_frequency AS examFrequency, ww.enabled AS enabled FROM wordbook_word ww INNER JOIN word w ON w.id = ww.word_id AND w.deleted = 0 WHERE ww.deleted = 0 AND ww.wordbook_id = #{wordbookId}
AND ww.enabled = #{enabled}
AND ( w.word LIKE CONCAT('%', #{keyword}, '%') OR w.normalized_word LIKE CONCAT('%', #{keyword}, '%') OR w.primary_definition LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY ww.sequence_no ASC, w.id ASC
